<?php
namespace App\Http\Controllers;
use App\Models\Order;use Illuminate\Http\Request;use Illuminate\Support\Facades\Http;
class PaymentController extends Controller{
 public function start(Order $order){if(auth()->id()!==$order->user_id&&!session('guest_order_'.$order->id))abort(403);if($order->payment_status==='paid')return redirect()->route('checkout.success',$order);return match($order->payment_method){'VNPAY'=>$this->vnpay($order),'MOMO'=>$this->momo($order),default=>abort(404)};}
 private function vnpay(Order $o){$tmn=config('services.vnpay.tmn_code');$secret=config('services.vnpay.hash_secret');$url=config('services.vnpay.url');if(!$tmn||!$secret)return redirect()->route('checkout.success',$o)->with('warning','Chưa cấu hình thông tin VNPay sandbox. Đơn hàng vẫn được lưu và đang chờ thanh toán.');$v=['vnp_Version'=>'2.1.0','vnp_Command'=>'pay','vnp_TmnCode'=>$tmn,'vnp_Amount'=>(int)round($o->total*100),'vnp_CurrCode'=>'VND','vnp_TxnRef'=>$o->order_code,'vnp_OrderInfo'=>'Thanh toan don '.$o->order_code,'vnp_OrderType'=>'other','vnp_Locale'=>'vn','vnp_ReturnUrl'=>route('payment.vnpay.return'),'vnp_IpAddr'=>request()->ip(),'vnp_CreateDate'=>now()->format('YmdHis')];ksort($v);$query=http_build_query($v);$v['vnp_SecureHash']=hash_hmac('sha512',$query,$secret);return redirect()->away($url.'?'.http_build_query($v));}
 private function momo(Order $o){$partner=config('services.momo.partner_code');$access=config('services.momo.access_key');$secret=config('services.momo.secret_key');$endpoint=config('services.momo.endpoint');if(!$partner||!$access||!$secret)return redirect()->route('checkout.success',$o)->with('warning','Chưa cấu hình thông tin MoMo sandbox. Đơn hàng vẫn được lưu và đang chờ thanh toán.');$requestId=(string)now()->timestamp;$orderId=$o->order_code;$amount=(string)(int)round($o->total);$orderInfo='Thanh toan don '.$orderId;$redirect=route('payment.momo.return');$ipn=route('payment.momo.ipn');$extra='';$raw="accessKey=$access&amount=$amount&extraData=$extra&ipnUrl=$ipn&orderId=$orderId&orderInfo=$orderInfo& partnerCode=$partner&redirectUrl=$redirect&requestId=$requestId&requestType=captureWallet";$signature=hash_hmac('sha256',str_replace('& partnerCode','&partnerCode',$raw),$secret);$res=Http::timeout(20)->post($endpoint,['partnerCode'=>$partner,'requestId'=>$requestId,'amount'=>$amount,'orderId'=>$orderId,'orderInfo'=>$orderInfo,'redirectUrl'=>$redirect,'ipnUrl'=>$ipn,'extraData'=>$extra,'requestType'=>'captureWallet','signature'=>$signature,'lang'=>'vi']);if(!$res->successful()||!$res->json('payUrl'))return redirect()->route('checkout.success',$o)->with('warning','MoMo chưa tạo được phiên thanh toán. Vui lòng liên hệ PURE để được hỗ trợ.');return redirect()->away($res->json('payUrl'));}
 public function vnpayReturn(Request $r){$o=Order::where('order_code',$r->query('vnp_TxnRef'))->firstOrFail();$secret=config('services.vnpay.hash_secret');$hash=$r->query('vnp_SecureHash','');$data=$r->except(['vnp_SecureHash','vnp_SecureHashType']);ksort($data);$valid=$secret&&hash_equals(hash_hmac('sha512',http_build_query($data),$secret),$hash);if($valid&&$r->query('vnp_ResponseCode')==='00'&&(int)$r->query('vnp_Amount')===(int)round($o->total*100))$o->update(['payment_status'=>'paid','status'=>'processing']);return redirect()->route('checkout.success',$o)->with($o->fresh()->payment_status==='paid'?'success':'warning',$o->fresh()->payment_status==='paid'?'Thanh toán VNPay thành công.':'Không xác minh được thanh toán VNPay. Đơn hàng đang chờ xác nhận.');}
 public function momoReturn(Request $r){$o=Order::where('order_code',$r->query('orderId'))->firstOrFail();$secret=config('services.momo.secret_key');$access=config('services.momo.access_key');$raw='accessKey='.$access.'&amount='.$r->query('amount').'&extraData='.$r->query('extraData').'&message='.$r->query('message').'&orderId='.$r->query('orderId').'&orderInfo='.$r->query('orderInfo').'&orderType='.$r->query('orderType').'&partnerCode='.$r->query('partnerCode').'&payType='.$r->query('payType').'&requestId='.$r->query('requestId').'&responseTime='.$r->query('responseTime').'&resultCode='.$r->query('resultCode').'&transId='.$r->query('transId');$valid=$secret&&hash_equals(hash_hmac('sha256',$raw,$secret),$r->query('signature',''));if($valid&&(string)$r->query('resultCode')==='0'&&(int)$r->query('amount')===(int)round($o->total))$o->update(['payment_status'=>'paid','status'=>'processing']);return redirect()->route('checkout.success',$o)->with($o->fresh()->payment_status==='paid'?'success':'warning',$o->fresh()->payment_status==='paid'?'Thanh toán MoMo thành công.':'Không xác minh được thanh toán MoMo. Đơn hàng đang chờ xác nhận.');}
 public function momoIpn(Request $r){$secret=config('services.momo.secret_key');$access=config('services.momo.access_key');$raw='accessKey='.$access.'&amount='.$r->amount.'&extraData='.$r->extraData.'&message='.$r->message.'&orderId='.$r->orderId.'&orderInfo='.$r->orderInfo.'&orderType='.$r->orderType.'&partnerCode='.$r->partnerCode.'&payType='.$r->payType.'&requestId='.$r->requestId.'&responseTime='.$r->responseTime.'&resultCode='.$r->resultCode.'&transId='.$r->transId;if(!$secret||!hash_equals(hash_hmac('sha256',$raw,$secret),$r->signature??''))return response()->json(['message'=>'Invalid signature'],400);$o=Order::where('order_code',$r->orderId)->first();if($o&&(string)$r->resultCode==='0'&&(int)$r->amount===(int)round($o->total))$o->update(['payment_status'=>'paid','status'=>'processing']);return response()->json(['message'=>'OK']);}
}
